#include <map>
#include <set>
#include <string>
#include <vector>

struct Object { int id; int parent; std::string name; };

static void walk(int id, const std::map<int, std::vector<int>>& children, const std::set<int>& open, std::vector<int>& rows)
{
    rows.push_back(id);
    if (!open.count(id)) return;
    const auto it{ children.find(id) };
    if (it == children.end()) return;
    for (int child : it->second) walk(child, children, open, rows);
}

std::vector<int> displayOrder(const std::vector<Object>& objects, const std::set<int>& open)
{
    std::map<int, std::vector<int>> children;
    std::vector<int> roots;
    for (const Object& o : objects)
    {
        if (o.parent < 0) roots.push_back(o.id);
        else children[o.parent].push_back(o.id);
    }
    std::vector<int> rows;
    for (int r : roots) walk(r, children, open, rows);
    return rows;
}

unitTests:
const std::vector<Object> scene{ { 1, -1, "Level" }, { 2, 1, "Props" }, { 3, 2, "Rock" }, { 4, 1, "Lights" }, { 5, -1, "UI" } };
TEST("level open") { CHECK_EQ(displayOrder(scene, { 1 }), (std::vector<int>{ 1, 2, 4, 5 })); }
TEST("both open") { CHECK_EQ(displayOrder(scene, { 1, 2 }), (std::vector<int>{ 1, 2, 3, 4, 5 })); }
TEST("closed parent hides open child") { CHECK_EQ(displayOrder(scene, { 2 }), (std::vector<int>{ 1, 5 })); }
TEST("all closed") { CHECK_EQ(displayOrder(scene, {}), (std::vector<int>{ 1, 5 })); }
TEST("children listed before their parent") { CHECK_EQ(displayOrder({ { 7, 3, "c" }, { 3, -1, "p" } }, { 3 }), (std::vector<int>{ 3, 7 })); }

